public static int indexOfExtension(String filename) {
    // Return -1 for null input
    if (filename == null) {
        return -1;
    }

    // Find the last dot in the filename
    int lastDotIndex = filename.lastIndexOf('.');
    if (lastDotIndex == -1) {
        // No dot found
        return -1;
    }

    // Find the last path separator (handles both Unix '/' and Windows '\\')
    int lastSlashIndex = filename.lastIndexOf('/');
    int lastBackslashIndex = filename.lastIndexOf('\\');
    int lastSeparatorIndex = Math.max(lastSlashIndex, lastBackslashIndex);

    // If the last dot occurs after the last separator, it is an extension separator
    if (lastDotIndex > lastSeparatorIndex) {
        return lastDotIndex;
    }

    // No valid extension separator found
    return -1;
}

