public static byte convertHexDigit(byte b){
    // ASCII '0' to '9'
    if (b >= '0' && b <= '9') {
        return (byte)(b - '0');
    }
    // ASCII 'a' to 'f'
    if (b >= 'a' && b <= 'f') {
        return (byte)(b - 'a' + 10);
    }
    // ASCII 'A' to 'F'
    if (b >= 'A' && b <= 'F') {
        return (byte)(b - 'A' + 10);
    }
    // Invalid input
    throw new IllegalArgumentException("Invalid hex digit: " + (char)b);
}

