private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        return false;
    }
    try {
        // Adjust previous node's next reference
        if (node.prev != null) {
            node.prev.next = node.next;
        } else {
            // node is the head
            head = node.next;
        }

        // Adjust next node's prev reference
        if (node.next != null) {
            node.next.prev = node.prev;
        } else {
            // node is the tail
            tail = node.prev;
        }

        // Clear the node's own links
        node.prev = null;
        node.next = null;

        // Update size
        size--;

        return true;
