public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> segments = new java.util.ArrayList<>();
    if (u == null) {
        return segments;
    }
    String path = u.getPath();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' if present (absolute path)
    if (path.charAt(0) == '/') {
        path = path.substring(1);
    }
    // Split by '/' and process each segment
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue; // ignore empty segments
        }
        if (decode) {
            try {
                part = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; wrap in runtime exception if it ever fails
                throw new RuntimeException("UTF-8 decoding not supported", e);
            }
        }
        segments.add(new PathSegmentImpl(part));
    }
    return segments;
}

