public static void addToClassPath(Vector<URL> cpV, String dir) {
    if (cpV == null) {
        throw new IllegalArgumentException("Classpath vector cannot be null");
    }
    if (dir == null) {
        throw new IllegalArgumentException("Directory path cannot be null");
    }

    File dirFile = new File(dir);
    if (!dirFile.exists() || !dirFile.isDirectory()) {
        throw new IllegalArgumentException("Provided path is not a valid directory: " + dir);
    }

    File[] jarFiles = dirFile.listFiles(new FilenameFilter() {
        @Override
        public boolean accept(File d, String name) {
            return name.toLowerCase().endsWith(".jar");
        }
    });

    if (jarFiles == null) {
        throw new IllegalArgumentException("Unable to list files in directory: " + dir);
    }

    for (File jar : jarFiles) {
        try {
            URL jarUrl = jar.toURI().toURL();
            cpV.add(jarUrl);
        } catch (MalformedURLException e) {
            // Log and continue with next file
            System.err.println("Failed to convert file to URL: " + jar.getAbsolutePath());
            e.printStackTrace();
        } catch (SecurityException e) {
            System.err.println("Security exception while accessing file: " + jar.getAbsolutePath());
            e.printStackTrace();
        }
    }
}

