protected void append(LoggingEvent event) {
    // Guard against null event
    if (event == null) {
        return;
    }

    // Retrieve the rendered message; skip if null
    String message = event.getRenderedMessage();
    if (message == null) {
        return;
    }

    // If there are no clients, nothing to do
    if (clients == null) {
        return;
    }

    // Iterate over the connected clients and send the message
    synchronized (clients) {
        Iterator<Socket> it = clients.iterator();
        while (it.hasNext()) {
            Socket socket = it.next();
            if (socket == null) {
                // Remove null references to keep the set clean
                it.remove();
                continue;
            }

            try {
                PrintWriter out = new PrintWriter(socket.getOutputStream(), true);
                out.println(message);
            } catch (IOException ioEx) {
                // If writing fails, remove the client and log the error
                it.remove();
                System.err.println("Failed to send log message to client: " + ioEx.getMessage());
            } catch (Exception ex) {
                // Catch any other unexpected exceptions to avoid breaking the loop
                it.remove();
                System.err.println("Unexpected error while sending log message: " + ex.getMessage());
            }
        }
    }
}

