    if (buf == null) {
        throw new NullPointerException("StringBuffer buf cannot be null");
    }
    // Assume the class has a field named 'name' containing the full name string
    String name = this.name; // this field must exist in the containing class
    if (name == null) {
        throw new IllegalArgumentException("Name cannot be null");
    }
    if (nameStart < 0 || nameStart >= name.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }

    int i = nameStart;

    // Skip any leading non-alphanumeric characters
    while (i < name.length() && !Character.isLetterOrDigit(name.charAt(i))) {
        i++;
    }

    boolean firstWord = true;
    while (i < name.length()) {
        // Start of a word
        char firstChar = name.charAt(i);
        if (Character.isLetterOrDigit(firstChar)) {
            buf.append(firstChar);
            // Append a dot after each word except the last
            // We'll determine if there's another word after this one
            int j = i + 1;
            while (j < name.length() && Character.isLetterOrDigit(name.charAt(j))) {
                j++;
            }
            // Skip non-word characters to find next word
            int k = j;
            while (k < name.length() && !Character.isLetterOrDigit(name.charAt(k))) {
                k++;
            }
            if (k < name.length()) {
                buf.append('.');
            }
        }
        // Move to the next word
        i = j;
        while (i < name.length() && !Character.isLetterOrDigit(name.charAt(i))) {
            i++;
        }
    }
}

