static long compressTimeBucket(long timeBucket,int dayStep){
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day = (int)(timeBucket % 100);
    try{
        java.time.LocalDate date = java.time.LocalDate.of(year, month, day);
        int remainder = day % dayStep;
        int newDay;
        if(remainder == 0){
            newDay = day;
        }else{
            newDay = day - (remainder - 1);
        }
        java.time.LocalDate newDate = java.time.LocalDate.of(year, month, newDay);
        return newDate.getYear() * 10000L + newDate.getMonthValue() * 100L + newDate.getDayOfMonth();
    }catch(java.time.DateTimeException e){
        // If the input date is invalid, return the original value
        return timeBucket;
    }
}

