    java.util.List<SequenceRange> ranges = new java.util.ArrayList<>();
    try {
        java.util.List<Profile> profiles = this.currentProfiles;
        if (profiles == null) {
            return java.util.Collections.emptyList();
        }
        for (Profile profile : profiles) {
            if (profile == null) {
                continue;
            }
            SegmentSnapshot snapshot = profile.getSegmentSnapshot();
            if (snapshot == null) {
                continue;
            }
            java.util.List<SequenceRange> seqRanges = snapshot.getSearchSequenceRanges();
            if (seqRanges == null) {
                continue;
            }
            ranges.addAll(seqRanges);
        }
    } catch (Exception e) {
        // Optionally log the exception
        return java.util.Collections.emptyList();
    }
    return ranges;
}

