    // Validate inputs
    if (file == null) {
        throw new IllegalArgumentException("file must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IllegalArgumentException("file does not exist or is not a regular file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        // No ranges to filter, return empty list
        return new java.util.ArrayList<>();
    }

    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();

    // Prepare reflection helpers for ProfileAnalyzeTimeRange
    java.lang.reflect.Method getStartMethod = null;
    java.lang.reflect.Method getEndMethod = null;
    try {
        getStartMethod = ProfileAnalyzeTimeRange.class.getMethod("getStartTime");
        getEndMethod = ProfileAnalyzeTimeRange.class.getMethod("getEndTime");
    } catch (NoSuchMethodException e) {
        // If the methods are not found, we cannot filter by time, so return empty list
        return result;
    }

    // Prepare constructor for ThreadSnapshot that accepts a String
    java.lang.reflect.Constructor<ThreadSnapshot> snapshotCtor = null;
    try {
        snapshotCtor = ThreadSnapshot.class.getConstructor(String.class);
    } catch (NoSuchMethodException e) {
        // If no such constructor, we cannot create snapshots, return empty list
        return result;
    }

    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            if (line.isEmpty()) {
                continue;
            }
            // Attempt to extract a timestamp from the beginning of the line
            String[] parts = line.split("\\s+", 2);
            if (parts.length == 0) {
                continue;
            }
            long timestamp;
            try {
                timestamp = Long.parseLong(parts[0]);
            } catch (NumberFormatException e) {
                // Not a numeric timestamp, skip this line
                continue;
            }

            // Check if timestamp falls within any of the provided ranges
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                try {
                    long start = (long) getStartMethod.invoke(range);
                    long end = (long) getEndMethod.invoke(range);
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
                    }
                } catch (IllegalAccessException | java.lang.reflect.InvocationTargetException ex) {
                    // Skip this range if we cannot access its times
                    continue;
                }
            }
            if (!inRange) {
                continue;
            }

            // Create a ThreadSnapshot instance
            try {
                ThreadSnapshot snapshot = snapshotCtor.newInstance(line);
                result.add(snapshot);
            } catch (InstantiationException | IllegalAccessException | java.lang.reflect.InvocationTargetException ex) {
                // Skip this line if we cannot instantiate a snapshot
                continue;
            }
        }
    }

    return result;
}

