@SuppressWarnings("unchecked") public String toString(JSONWriter.Feature... features){
    try {
        // Ensure features is not null
        if (features == null) {
            features = new JSONWriter.Feature[0];
        }
        // Filter out any null entries in the features array
        int nonNullCount = 0;
        for (JSONWriter.Feature f : features) {
            if (f != null) {
                nonNullCount++;
            }
        }
        if (nonNullCount == features.length) {
            // No nulls, use the original array
            return JSONWriter.writeObject(this, features);
        }
        JSONWriter.Feature[] filtered = new JSONWriter.Feature[nonNullCount];
        int idx = 0;
        for (JSONWriter.Feature f : features) {
            if (f != null) {
                filtered[idx++] = f;
            }
        }
        return JSONWriter.writeObject(this, filtered);
    } catch (Exception e) {
        // Wrap any exception in a runtime exception with a clear message
        throw new RuntimeException("Failed to serialize object to JSON", e);
    }
}

